import { memo, useCallback, useMemo, useState } from 'react';

import EditOutlined from '@mui/icons-material/EditOutlined';
import PeopleOutlined from '@mui/icons-material/PeopleOutline';
import { Box, Chip, IconButton, LinearProgress, Skeleton, Tooltip, Typography } from '@mui/material';

import {
  GridTableBody,
  GridTableContainer,
  GridTableHeader,
  GridTablePagination,
  GridTableRow,
} from '@/components/GridTable';
import { useResponsiveColumns } from '@/hooks/useResponsiveColumns.hooks';
import { formatLimit, formatMoney, usageColor } from '@/pages/BudgetsPage/helpers/budgetFormat.helpers';

const PAGE_SIZE_OPTIONS = [10, 20, 50, 100];

const SOURCE_CONFIG = {
  explicit: {
    label: 'Explicit',
    color: 'primary',
    hint: 'Set directly for this project',
  },
  default: {
    label: 'Default',
    color: 'info',
    hint: 'Inherited from the platform default, not set for this project',
  },
  unlimited: {
    label: 'Unlimited',
    color: 'default',
    hint: 'No limit applies to this project',
  },
};

// Budget columns are identical on both tabs; only the identity columns differ.
// None of these three is a project column — they come from stored budgets, config
// defaults and LiteLLM — so ordering by them could only ever sort the fetched page.
// Ranking by cost belongs in the Excel export, which holds every record.
const BUDGET_COLUMNS = [
  { field: 'effective_limit', label: 'Limit', width: '8rem', sortable: false },
  { field: 'spend', label: 'Spent', width: '8rem', sortable: false },
  { field: 'percent_used', label: 'Used', width: '10rem', sortable: false },
  {
    field: 'limit_source',
    label: 'Source',
    width: '7rem',
    sortable: false,
    hideBelow: 1100,
  },
  { field: 'actions', label: 'Actions', width: '8rem', sortable: false },
];

const ID_COLUMN = {
  field: 'project_id',
  label: 'ID',
  width: '5rem',
  sortable: true,
};

const TEAM_COLUMNS = [
  { field: 'name', label: 'Name', width: '1.2fr', sortable: true },
  ID_COLUMN,
  ...BUDGET_COLUMNS,
];

// Owner and email are not columns on the project table, so neither can be sorted.
// Email drops out first on narrow screens: the owner name already identifies the row.
const PERSONAL_COLUMNS = [
  { field: 'name', label: 'Name', width: '1fr', sortable: true },
  ID_COLUMN,
  { field: 'owner_name', label: 'Owner', width: '1fr', sortable: false },
  {
    field: 'owner_email',
    label: 'Email',
    width: '1fr',
    sortable: false,
    hideBelow: 1500,
  },
  ...BUDGET_COLUMNS,
];

const BudgetsTable = memo(props => {
  const {
    rows = [],
    total = 0,
    page = 0,
    pageSize = 20,
    onPageChange,
    onPageSizeChange,
    sortConfig,
    onSort,
    isFetching,
    isPersonal,
    canEdit,
    onEdit,
    onUsers,
  } = props;

  const styles = useMemo(() => budgetsTableStyles(), []);

  const [hoveredRowId, setHoveredRowId] = useState(null);

  const { visibleColumns, dataColumns, gridTemplateColumns } = useResponsiveColumns({
    columns: isPersonal ? PERSONAL_COLUMNS : TEAM_COLUMNS,
    containerWidth: window.innerWidth,
    showCheckbox: false,
    actionsColumnWidth: '8rem',
  });

  const paginationProps = useMemo(
    () => ({
      totalRows: total,
      pageSize,
      isFirstPage: page === 0,
      isLastPage: (page + 1) * pageSize >= total,
      startRow: total > 0 ? page * pageSize + 1 : 0,
      endRow: Math.min((page + 1) * pageSize, total),
      handlePrevPage: () => onPageChange(Math.max(0, page - 1)),
      handleNextPage: () => onPageChange(page + 1),
      handlePageSizeChange: onPageSizeChange,
      pageSizeOptions: PAGE_SIZE_OPTIONS,
    }),
    [total, page, pageSize, onPageChange, onPageSizeChange],
  );

  const renderCell = useCallback(
    (column, value, row) => {
      if (column.field === 'name') {
        return (
          <Tooltip
            title={
              row?.is_personal
                ? "This user's own budget — API and token calls without a project land here"
                : value || ''
            }
            placement="top"
          >
            <Typography
              variant="bodyMedium"
              sx={styles.cellText}
            >
              {value || '-'}
            </Typography>
          </Tooltip>
        );
      }

      // Long identities need the full value on hover, since the cell ellipsises
      if (column.field === 'owner_name' || column.field === 'owner_email') {
        return (
          <Tooltip
            title={value || ''}
            placement="top"
          >
            <Typography
              variant="bodyMedium"
              sx={styles.cellText}
            >
              {value || '-'}
            </Typography>
          </Tooltip>
        );
      }

      if (column.field === 'limit_source') {
        const cfg = SOURCE_CONFIG[value] || SOURCE_CONFIG.unlimited;
        return (
          <Tooltip
            title={cfg.hint}
            placement="top"
          >
            <Chip
              label={cfg.label}
              size="small"
              color={cfg.color}
              variant="outlined"
            />
          </Tooltip>
        );
      }

      if (column.field === 'effective_limit') {
        return (
          <Typography
            variant="bodyMedium"
            sx={styles.cellText}
          >
            {formatLimit(value, row?.currency)}
          </Typography>
        );
      }

      if (column.field === 'spend') {
        return (
          <Typography
            variant="bodyMedium"
            sx={styles.cellText}
          >
            {formatMoney(value, row?.currency)}
          </Typography>
        );
      }

      if (column.field === 'percent_used') {
        if (value === null || value === undefined) {
          return (
            <Typography
              variant="bodyMedium"
              color="text.secondary"
              sx={styles.cellText}
            >
              -
            </Typography>
          );
        }
        const color = usageColor(value);
        return (
          <Box sx={styles.usageCell}>
            <LinearProgress
              variant="determinate"
              value={Math.min(100, value)}
              color={color}
              sx={styles.usageBar}
            />
            <Typography
              variant="bodySmall"
              color={`${color}.main`}
            >
              {value}%
            </Typography>
          </Box>
        );
      }

      return (
        <Typography
          variant="bodyMedium"
          sx={styles.cellText}
        >
          {value || '-'}
        </Typography>
      );
    },
    [styles],
  );

  const renderActions = useCallback(
    row => (
      <Box sx={styles.actionsRow}>
        {/* A personal project's only member is its owner, so its project budget already
            is that person's budget — offering a separate member budget would be two ways
            to set one limit. */}
        {!isPersonal && (
          <Tooltip title="Manage member budgets">
            <IconButton
              size="small"
              onClick={() => onUsers(row)}
            >
              <PeopleOutlined fontSize="small" />
            </IconButton>
          </Tooltip>
        )}
        <Tooltip title={canEdit ? 'Edit budget' : 'No permission to edit'}>
          <Box component="span">
            <IconButton
              size="small"
              disabled={!canEdit}
              onClick={() => onEdit(row)}
            >
              <EditOutlined fontSize="small" />
            </IconButton>
          </Box>
        </Tooltip>
      </Box>
    ),
    [styles, canEdit, isPersonal, onEdit, onUsers],
  );

  if (isFetching) {
    return (
      <Box sx={styles.skeletonContainer}>
        {Array.from({ length: 10 }).map((_, index) => (
          <Skeleton
            key={index}
            variant="rectangular"
            width="100%"
            height="2.5rem"
            sx={{ marginBottom: '0.5rem' }}
          />
        ))}
      </Box>
    );
  }

  return (
    <Box sx={styles.tableContainer}>
      <GridTableContainer
        isLoading={false}
        isEmpty={rows.length === 0}
        emptyMessage="No projects"
      >
        <GridTableHeader
          columns={visibleColumns}
          sortConfig={sortConfig}
          onSort={onSort}
          gridTemplateColumns={gridTemplateColumns}
          showCheckbox={false}
        />

        <GridTableBody>
          {rows.map(row => (
            <GridTableRow
              key={row.project_id}
              row={row}
              columns={dataColumns}
              isHovered={hoveredRowId === row.project_id}
              onMouseEnter={() => setHoveredRowId(row.project_id)}
              onMouseLeave={() => setHoveredRowId(null)}
              gridTemplateColumns={gridTemplateColumns}
              showCheckbox={false}
              renderCell={(column, value) => renderCell(column, value, row)}
              renderActions={renderActions}
            />
          ))}
        </GridTableBody>

        {total > 0 && <GridTablePagination {...paginationProps} />}
      </GridTableContainer>
    </Box>
  );
});

BudgetsTable.displayName = 'BudgetsTable';

/** @type {MuiSx} */
const budgetsTableStyles = () => ({
  tableContainer: {
    height: '100%',
    width: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  skeletonContainer: {
    padding: '1rem',
  },
  cellText: {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  },
  usageCell: {
    display: 'flex',
    alignItems: 'center',
    gap: '0.5rem',
    width: '100%',
  },
  usageBar: {
    flexGrow: 1,
    height: '0.375rem',
    borderRadius: '0.25rem',
  },
  actionsRow: {
    display: 'flex',
    alignItems: 'center',
    gap: '0.25rem',
  },
});

export default BudgetsTable;
