import { memo, useCallback, useMemo, useState } from 'react';

import cronstrue from 'cronstrue';
import { Link } from 'react-router-dom';

import LockOutlined from '@mui/icons-material/LockOutlined';
import { Box, Input, Switch, Tooltip, Typography } from '@mui/material';

import { GridTableBody, GridTableContainer, GridTableHeader, GridTableRow } from '@/components/GridTable';
import { PERMISSIONS } from '@/constants/permissions.constants';
import { RouteDefinitions } from '@/constants/routes.constants';
import { useCheckPermission } from '@/hooks/useCheckPermission.hooks';
import { useResponsiveColumns } from '@/hooks/useResponsiveColumns.hooks';

const SCHEDULE_COLUMNS = [
  { field: 'name', label: 'Name', width: '1fr', sortable: true },
  { field: 'cron', label: 'Cron', width: '14rem', sortable: false },
  { field: 'active', label: 'Active', width: '5rem', sortable: false },
  { field: 'rpc_func', label: 'Function', width: '1fr', sortable: true },
  { field: 'last_run', label: 'Last Run', width: '12rem', sortable: true },
];

const CONFIG_SECTION_TITLES = {
  runtime: 'Runtime',
};

const describeConfigLocation = managedBy => {
  const title = CONFIG_SECTION_TITLES[managedBy?.section];
  return title ? `Managed in Configuration \u2192 ${title}` : 'Managed by the platform configuration';
};

const describeCron = expr => {
  try {
    return cronstrue.toString(expr, { use24HourTimeFormat: true });
  } catch {
    return '';
  }
};

const SchedulesTable = memo(props => {
  const { schedules, sortConfig, onSort, onToggleActive, onCronUpdate, onScheduleClick } = props;

  const styles = useMemo(() => schedulesTableStyles(), []);

  const { hasPermission } = useCheckPermission();
  const canOpenConfiguration = hasPermission(PERMISSIONS.runtime.plugins);

  const [editingCronId, setEditingCronId] = useState(null);
  const [cronDraft, setCronDraft] = useState('');
  const [hoveredRowId, setHoveredRowId] = useState(null);

  const { visibleColumns, dataColumns, gridTemplateColumns } = useResponsiveColumns({
    columns: SCHEDULE_COLUMNS,
    containerWidth: window.innerWidth,
    showCheckbox: false,
  });

  const handleCronClick = useCallback(schedule => {
    setEditingCronId(schedule.id);
    setCronDraft(schedule.cron);
  }, []);

  const handleCronBlur = useCallback(
    schedule => {
      setEditingCronId(null);
      onCronUpdate(schedule, cronDraft.trim());
    },
    [cronDraft, onCronUpdate],
  );

  const handleCronKeyDown = useCallback(
    (e, schedule) => {
      if (e.key === 'Enter') {
        setEditingCronId(null);
        onCronUpdate(schedule, cronDraft.trim());
      }
      if (e.key === 'Escape') {
        setEditingCronId(null);
      }
    },
    [cronDraft, onCronUpdate],
  );

  const renderCell = useCallback(
    (column, value, row) => {
      if (column.field === 'name') {
        return (
          <Box sx={styles.nameCell}>
            <Typography
              variant="bodyMedium"
              color="text.secondary"
              onClick={() => onScheduleClick(row)}
              sx={styles.nameText}
            >
              {value}
            </Typography>
            {row.managed_by && (
              <Tooltip title={describeConfigLocation(row.managed_by)}>
                {canOpenConfiguration && CONFIG_SECTION_TITLES[row.managed_by.section] ? (
                  <Box
                    component={Link}
                    to={`${RouteDefinitions.Configuration}#${row.managed_by.section}`}
                    aria-label={describeConfigLocation(row.managed_by)}
                    sx={styles.managedLink}
                  >
                    <LockOutlined sx={styles.managedIcon} />
                  </Box>
                ) : (
                  <LockOutlined sx={styles.managedIcon} />
                )}
              </Tooltip>
            )}
          </Box>
        );
      }

      if (column.field === 'active') {
        const toggleable = onToggleActive && !row.managed_by;
        const control = (
          <Switch
            size="small"
            checked={!!value}
            onChange={toggleable ? () => onToggleActive(row) : undefined}
            disabled={!toggleable}
          />
        );
        if (!row.managed_by) return control;
        return (
          <Tooltip title={describeConfigLocation(row.managed_by)}>
            <Box component="span">{control}</Box>
          </Tooltip>
        );
      }

      if (column.field === 'cron') {
        const editable = onCronUpdate && !row.managed_by;
        if (editable && editingCronId === row.id) {
          return (
            <Input
              autoFocus
              disableUnderline
              value={cronDraft}
              onChange={e => setCronDraft(e.target.value)}
              onBlur={() => handleCronBlur(row)}
              onKeyDown={e => handleCronKeyDown(e, row)}
              sx={styles.cronInput}
            />
          );
        }
        const desc = describeCron(value);
        return (
          <Box
            onClick={editable ? () => handleCronClick(row) : undefined}
            sx={editable ? styles.cronCell : styles.cronCellReadOnly}
          >
            <Typography
              variant="bodyMedium"
              color="text.secondary"
              sx={styles.cronText}
            >
              {value}
            </Typography>
            {desc && (
              <Typography
                variant="bodySmall"
                color="text.metrics"
                sx={styles.cronDesc}
              >
                {desc}
              </Typography>
            )}
          </Box>
        );
      }

      if (column.field === 'last_run') {
        if (!value) {
          return (
            <Typography
              variant="bodyMedium"
              color="text.metrics"
              sx={styles.cellText}
            >
              Never
            </Typography>
          );
        }
        try {
          return (
            <Typography
              variant="bodyMedium"
              color="text.secondary"
              sx={styles.cellText}
            >
              {new Date(value).toLocaleString()}
            </Typography>
          );
        } catch {
          return String(value);
        }
      }

      return (
        <Typography
          variant="bodyMedium"
          color="text.secondary"
          sx={styles.cellText}
        >
          {value || '\u2014'}
        </Typography>
      );
    },
    [
      styles,
      canOpenConfiguration,
      onToggleActive,
      onCronUpdate,
      onScheduleClick,
      editingCronId,
      cronDraft,
      handleCronClick,
      handleCronBlur,
      handleCronKeyDown,
    ],
  );

  const getRowSx = useCallback(
    row => {
      if (!row.active) return styles.inactiveRow;
      return undefined;
    },
    [styles],
  );

  return (
    <Box sx={styles.tableContainer}>
      <GridTableContainer
        isLoading={false}
        isEmpty={schedules.length === 0}
        emptyMessage="No schedules found"
      >
        <GridTableHeader
          columns={visibleColumns}
          sortConfig={sortConfig}
          onSort={onSort}
          gridTemplateColumns={gridTemplateColumns}
          showCheckbox={false}
        />

        <GridTableBody>
          {schedules.map(row => (
            <GridTableRow
              key={row.id}
              row={row}
              columns={dataColumns}
              isHovered={hoveredRowId === row.id}
              onMouseEnter={() => setHoveredRowId(row.id)}
              onMouseLeave={() => setHoveredRowId(null)}
              gridTemplateColumns={gridTemplateColumns}
              showCheckbox={false}
              renderCell={renderCell}
              rowSx={getRowSx(row)}
            />
          ))}
        </GridTableBody>
      </GridTableContainer>
    </Box>
  );
});

SchedulesTable.displayName = 'SchedulesTable';

/** @type {MuiSx} */
const schedulesTableStyles = () => ({
  tableContainer: {
    flex: 1,
    minHeight: 0,
    width: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  nameCell: {
    display: 'flex',
    alignItems: 'center',
    gap: '0.375rem',
    overflow: 'hidden',
  },
  managedLink: {
    display: 'inline-flex',
    alignItems: 'center',
    color: 'inherit',
  },
  managedIcon: {
    fontSize: '0.875rem',
    opacity: 0.6,
  },
  cellText: {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  },
  nameText: {
    cursor: 'pointer',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
    '&:hover': {
      textDecoration: 'underline',
    },
  },
  cronCell: {
    cursor: 'pointer',
    overflow: 'hidden',
    display: 'flex',
    flexDirection: 'column',
    gap: '0.125rem',
    '&:hover .MuiTypography-root:first-of-type': {
      textDecoration: 'underline',
    },
  },
  cronCellReadOnly: {
    overflow: 'hidden',
    display: 'flex',
    flexDirection: 'column',
    gap: '0.125rem',
  },
  cronText: {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
    fontFamily: 'monospace',
  },
  cronDesc: {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
    fontSize: '0.6875rem',
    lineHeight: 1.2,
    opacity: 0.7,
  },
  cronInput: ({ palette }) => ({
    fontSize: '0.8125rem',
    fontFamily: 'monospace',
    padding: '0.125rem 0.375rem',
    backgroundColor: palette.background.userInputBackgroundActive,
    borderRadius: '0.25rem',
    width: '100%',
  }),
  inactiveRow: ({ palette }) => ({
    opacity: 0.5,
    backgroundColor: palette.background.subtle.default,
  }),
});

export default SchedulesTable;
