import { memo, useCallback, useMemo, useState } from 'react';

import DescriptionOutlined from '@mui/icons-material/DescriptionOutlined';
import PlayArrowOutlined from '@mui/icons-material/PlayArrowOutlined';
import StopOutlined from '@mui/icons-material/StopOutlined';
import { Box, Button, Chip, IconButton, Tooltip, Typography } from '@mui/material';
import { useTheme } from '@mui/material/styles';

import { GridTableBody, GridTableContainer, GridTableHeader, GridTableRow } from '@/components/GridTable';
import { useResponsiveColumns } from '@/hooks/useResponsiveColumns.hooks';
import { json } from '@codemirror/lang-json';
import { vscodeDarkInit, vscodeLightInit } from '@uiw/codemirror-theme-vscode';
import CodeMirror from '@uiw/react-codemirror';

const STATUS_CONFIG = {
  running: { label: 'Running', color: 'success' },
  done: { label: 'Done', color: 'default' },
  finished: { label: 'Finished', color: 'default' },
  error: { label: 'Error', color: 'error' },
  stopped: { label: 'Stopped', color: 'warning' },
};

const INSTANCE_COLUMNS = [
  { field: 'status', label: 'Status', width: '7rem', sortable: false },
  { field: 'task_id', label: 'Task ID', width: '1fr', sortable: false },
  {
    field: 'user',
    label: 'User',
    width: '12rem',
    sortable: false,
    hideBelow: 900,
  },
  {
    field: 'started_at',
    label: 'Started',
    width: '13rem',
    sortable: false,
    hideBelow: 800,
  },
  { field: 'actions', label: '', width: '5rem', sortable: false },
];

const JSON_EXTENSIONS = [json()];

const formatDateTime = iso => {
  if (!iso) return '\u2014';
  try {
    return new Date(iso).toLocaleString();
  } catch {
    return iso;
  }
};

const TaskDetail = memo(props => {
  const { taskName, taskDescription, instances, onStart, onStop, onOpenLogs, isStarting } = props;

  const styles = useMemo(() => taskDetailStyles(), []);

  const [param, setParam] = useState('');
  const [hoveredRowId, setHoveredRowId] = useState(null);
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  const cmTheme = useMemo(
    () =>
      isDark
        ? vscodeDarkInit({
            settings: {
              background: theme.palette.background.default,
              gutterBackground: theme.palette.background.default,
            },
          })
        : vscodeLightInit({
            settings: {
              background: theme.palette.background.default,
              gutterBackground: theme.palette.background.default,
            },
          }),
    [isDark, theme.palette.background.default],
  );

  const { visibleColumns, dataColumns, gridTemplateColumns } = useResponsiveColumns({
    columns: INSTANCE_COLUMNS,
    containerWidth: window.innerWidth,
    showCheckbox: false,
    actionsColumnWidth: '5rem',
  });

  const handleStart = useCallback(() => {
    onStart(taskName, param);
    setParam('');
  }, [taskName, param, onStart]);

  const renderCell = useCallback(
    (column, value) => {
      if (column.field === 'status') {
        const statusLower = (value || '').toLowerCase();
        const cfg = STATUS_CONFIG[statusLower] || {
          label: value || 'Unknown',
          color: 'default',
        };
        return (
          <Chip
            label={cfg.label}
            size="small"
            color={cfg.color}
            variant="outlined"
          />
        );
      }

      if (column.field === 'task_id') {
        return (
          <Tooltip title={value || ''}>
            <Typography
              variant="bodyMedium"
              sx={styles.cellTextMono}
            >
              {value || '\u2014'}
            </Typography>
          </Tooltip>
        );
      }

      if (column.field === 'started_at') {
        return (
          <Typography
            variant="bodyMedium"
            color="text.secondary"
            sx={styles.cellText}
          >
            {formatDateTime(value)}
          </Typography>
        );
      }

      if (column.field === 'user') {
        return (
          <Tooltip title={value || ''}>
            <Typography
              variant="bodyMedium"
              color="text.secondary"
              sx={styles.cellText}
            >
              {value || '\u2014'}
            </Typography>
          </Tooltip>
        );
      }

      return (
        <Typography
          variant="bodyMedium"
          color="text.secondary"
          sx={styles.cellText}
        >
          {value || '\u2014'}
        </Typography>
      );
    },
    [styles],
  );

  const renderActions = useCallback(
    row => {
      const isRunning = (row.status || '').toLowerCase() === 'running';
      return (
        <Box sx={styles.actionsRow}>
          <Tooltip title="View logs">
            <IconButton
              size="small"
              onClick={() => onOpenLogs(row.task_id)}
            >
              <DescriptionOutlined fontSize="small" />
            </IconButton>
          </Tooltip>
          {isRunning && (
            <Tooltip title="Stop task">
              <IconButton
                size="small"
                onClick={() => onStop(row.task_id)}
              >
                <StopOutlined
                  fontSize="small"
                  color="error"
                />
              </IconButton>
            </Tooltip>
          )}
        </Box>
      );
    },
    [styles, onStop, onOpenLogs],
  );

  return (
    <Box sx={styles.container}>
      <Box sx={styles.header}>
        <Box sx={styles.headerTop}>
          <Typography sx={styles.title}>{taskName}</Typography>
          <Button
            variant="contained"
            size="small"
            startIcon={<PlayArrowOutlined />}
            onClick={handleStart}
            disabled={isStarting}
            sx={styles.startButton}
          >
            Start
          </Button>
        </Box>
        {taskDescription && (
          <Box sx={styles.descriptionArea}>
            <Typography
              variant="bodySmall"
              color="text.metrics"
              sx={styles.description}
            >
              {taskDescription}
            </Typography>
          </Box>
        )}
      </Box>

      <Box sx={styles.editorArea}>
        <Typography
          variant="bodySmall"
          color="text.metrics"
          sx={styles.editorLabel}
        >
          Parameters (string | json)
        </Typography>
        <Box sx={styles.editorWrapper}>
          <CodeMirror
            value={param}
            onChange={setParam}
            extensions={JSON_EXTENSIONS}
            theme={cmTheme}
            placeholder="String or JSON"
            basicSetup={{
              lineNumbers: false,
              foldGutter: false,
              highlightActiveLine: false,
            }}
          />
        </Box>
      </Box>

      <Box sx={styles.tableArea}>
        <GridTableContainer
          isLoading={false}
          isEmpty={instances.length === 0}
          emptyMessage="No recent runs for this task"
        >
          <GridTableHeader
            columns={visibleColumns}
            gridTemplateColumns={gridTemplateColumns}
            showCheckbox={false}
          />

          <GridTableBody>
            {instances.map(row => (
              <GridTableRow
                key={row.task_id}
                row={row}
                columns={dataColumns}
                isHovered={hoveredRowId === row.task_id}
                onMouseEnter={() => setHoveredRowId(row.task_id)}
                onMouseLeave={() => setHoveredRowId(null)}
                gridTemplateColumns={gridTemplateColumns}
                showCheckbox={false}
                renderCell={renderCell}
                renderActions={renderActions}
              />
            ))}
          </GridTableBody>
        </GridTableContainer>
      </Box>
    </Box>
  );
});

TaskDetail.displayName = 'TaskDetail';

/** @type {MuiSx} */
const taskDetailStyles = () => ({
  container: {
    display: 'flex',
    flexDirection: 'column',
    height: '100%',
    overflow: 'hidden',
  },
  header: {
    display: 'flex',
    flexDirection: 'column',
    padding: '0.75rem 1.5rem 0',
    flexShrink: 0,
  },
  headerTop: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: '0.5rem',
  },
  title: {
    fontSize: '0.875rem',
    fontWeight: 600,
  },
  descriptionArea: {
    maxHeight: '16rem',
    overflowY: 'auto',
    marginTop: '0.25rem',
  },
  description: {
    fontSize: '0.75rem',
    lineHeight: 1.4,
    whiteSpace: 'pre-line',
  },
  startButton: {
    textTransform: 'none',
    fontWeight: 500,
    whiteSpace: 'nowrap',
    fontSize: '0.8125rem',
    flexShrink: 0,
  },
  editorArea: {
    padding: '0.5rem 1.5rem 0.75rem',
    flexShrink: 0,
  },
  editorLabel: {
    fontSize: '0.6875rem',
    fontWeight: 600,
    textTransform: 'uppercase',
    letterSpacing: '0.04em',
    marginBottom: '0.375rem',
  },
  editorWrapper: ({ palette }) => ({
    '& .cm-theme': {
      fontSize: '0.8125rem',
    },
    border: `0.0625rem solid ${palette.border.lines}`,
    borderRadius: '0.375rem',
    overflow: 'hidden',
    '& .cm-editor': {
      minHeight: '4rem',
      maxHeight: '10rem',
    },
    '& .cm-scroller': {
      overflow: 'auto',
    },
  }),
  tableArea: {
    flex: 1,
    overflow: 'auto',
  },
  cellText: {
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  },
  cellTextMono: {
    fontFamily: 'monospace',
    fontSize: '0.75rem',
    color: 'text.secondary',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
    whiteSpace: 'nowrap',
  },
  actionsRow: {
    display: 'flex',
    gap: '0.125rem',
  },
});

export default TaskDetail;
